import os
import torch


class Config:
    """
    Global configuration for the ZIMAR-Net (Zero-Initialized Metric-Aligned Residual Network) pipeline.
    """

    # =========================================================================
    # Paths & Directories
    # =========================================================================
    INPUT_DIR = "./input"
    TRAIN_IMG_DIR = os.path.join(INPUT_DIR, "train")
    TEST_IMG_DIR = os.path.join(INPUT_DIR, "test")

    # Metadata generated by the analysis script
    METADATA_DIR = "./metadata"
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")
    SAMPLE_SUBMISSION = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Working directory for artifacts (Cache and Checkpoints)
    WORKING_DIR = "./working/idea_31"
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")
    CHECKPOINT_DIR = os.path.join(WORKING_DIR, "checkpoints")
    BEST_MODEL_PATH = os.path.join(CHECKPOINT_DIR, "best_model.pth")

    # Submission Output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # =========================================================================
    # Data Preprocessing
    # =========================================================================
    # Radiological Windowing (Lung Window)
    WINDOW_LEVEL = -600
    WINDOW_WIDTH = 1500

    # Image Dimensions (EfficientNet-B2 native)
    IMAGE_SIZE = 260

    # Slice Selection Strategy
    NUM_SLICES = 3  # 1 Anchor (Max Area) + 2 Boundaries

    # Normalization (Standard ImageNet stats)
    IMAGENET_MEAN = [0.485, 0.456, 0.406]
    IMAGENET_STD = [0.229, 0.224, 0.225]

    # =========================================================================
    # Model Architecture
    # =========================================================================
    BACKBONE_NAME = "efficientnet_b2"
    PROJECTION_DIM = 64
    MLP_HIDDEN_DIM = 128
    MLP_OUT_DIM = 64

    # =========================================================================
    # Training Hyperparameters
    # =========================================================================
    SEED = 42
    BATCH_SIZE = 32
    EPOCHS = 50

    # Differential Learning Rates
    LR_BACKBONE = 1e-4  # Lower for fine-tuning
    LR_MLP = 1e-3  # Higher for new layers

    WEIGHT_DECAY = 0.01
    NUM_WORKERS = 4
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # Scheduler (Cosine Annealing)
    T_MAX = EPOCHS
    ETA_MIN = 1e-6

    # =========================================================================
    # Metric & Post-processing
    # =========================================================================
    SIGMA_MIN = 70.0
    MAX_DELTA = 1000.0

    # =========================================================================
    # Debugging & Development
    # =========================================================================
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 50  # Number of samples to use when DEBUG is True

    @classmethod
    def setup(cls):
        """Creates necessary directories for cache, checkpoints, and submission."""
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.CHECKPOINT_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

    @classmethod
    def print_config(cls):
        """Prints the current configuration."""
        print("=" * 30)
        print("       CONFIG       ")
        print("=" * 30)
        print(f"Device: {cls.DEVICE}")
        print(f"Backbone: {cls.BACKBONE_NAME}")
        print(f"Image Size: {cls.IMAGE_SIZE}x{cls.IMAGE_SIZE}")
        print(f"Batch Size: {cls.BATCH_SIZE}")
        print(f"Epochs: {cls.EPOCHS}")
        print(f"LR Backbone: {cls.LR_BACKBONE}")
        print(f"LR MLP: {cls.LR_MLP}")
        print(f"Cache Dir: {cls.CACHE_DIR}")
        print("=" * 30)
